import React, { useEffect, useRef, useState } from "react";
import {
  useLocation,
  useNavigate,
  useNavigation,
  useParams,
} from "react-router-dom";
import useApi from "../../../hooks/useApi";

import { BsTrash } from "react-icons/bs";
import {
  Avatar,
  Card,
  CardFooter,
  CardHeader,
  CardBody,
  Input,
  Divider,
  Tab,
  Tabs,
  RadioGroup,
} from "@heroui/react";
import {
  CustomInput,
  Loading,
  SearchIcon,
  YesNoModal,
} from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import useScreenSize from "../../../hooks/useScreenSize";
import { ToastContainer, toast } from "react-toastify";
import { Button } from "@heroui/react";
import customerOrdersApi from "../../../api/retailers/customerOrdersApi";
import {
  DeleteForeverTwoTone,
  DiscountTwoTone,
  Edit,
  RefreshRounded,
} from "@mui/icons-material";
import { useDispatch, useSelector } from "react-redux";
import { getRetailerReceipts } from "../../../redux/retailers/receipts/actions";
import "react-toastify/dist/ReactToastify.css";
import { CardTitle } from "reactstrap";
import { usePageVisibility } from "../../../hooks/userPageVisibility";
import retailersApi from "../../../api/retailers/retailersApi";

function RetailerIndentDetails() {
  const [selected, setSelected] = React.useState();
  const screenSize = useScreenSize();
  const { id } = useParams();

  const [openYesNoModal, setopenYesNoModal] = useState(false);

  console.log("Indent ID", id);

  const location = useLocation();

  console.log("loc", location.state);
  const [selectedIndent, setselectedIndent] = useState();

  const { dangerColor } = useStateContext();

  const dispatch = useDispatch();

  const loading = useSelector((state) => state.RetailerReceipts.loading);

  const [data, setdata] = useState([]);
  const [errors, setErrors] = useState([]);
  const { currentColor } = useStateContext();

  const [selectedOrderItems, setselectedOrderItems] = useState([]);
  const [indentId, setindentId] = useState(id);

  const getTotalValue = (items) => {
    let totalValue = 0.0;
    for (let x of items) {
      totalValue += x.required_quantity * x.final_pack_price;
    }

    return totalValue;
  };

  useEffect(() => {
    console.log("my data", data);
  }, [data]);

  const customerOrderActionsApi = useApi(
    customerOrdersApi.customerOrdersActionAdmin
  );

  const handleFilter = (e) => {
    const search_param = e.target.value;

    if (
      indentItemsApi.data &&
      indentItemsApi.data.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        indentItemsApi.data.data.filter((x) =>
          x.wholesale_receipt_title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(indentItemsApi.data);
    }
  };

  //   const navigate = useNavigation();
  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
      // Your polling logic here
      console.log("Polling...");
      dispatch(getRetailerReceipts({ action: "GetRetailerReceipts" }));
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 10 seconds
      timerIdRef.current = setInterval(pollingCallback, 200000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled]);

  const removeItemApi = useApi(retailersApi.retailerOrdersStaffAction);

  const handleRemoveFromIndent = async (item) => {
    console.log("Item", item);
    const data = {
      action: "RemoveRetailerIndentItem",
      retailer_indent: item.retailer_indent,
      retailer_indent_item: item.id,
    };

    await removeItemApi.request(data);
  };

  useEffect(() => {
    console.log("removeItemApi.data", removeItemApi.data);
    if (removeItemApi.data) {
      retrieveIndentItems(indentId);
    }
  }, [removeItemApi.data]);

  const indentItemsApi = useApi(retailersApi.retailerOrdersStaffAction);

  const retrieveIndentItems = async (indentId) => {
    await indentItemsApi.request({
      action: "RetrieveRetailerIndentItems",
      retailer_indent: indentId,
    });
  };

  useEffect(() => {
    console.log("indentItemsApi.data", indentItemsApi.data);
    if (
      indentItemsApi.data &&
      indentItemsApi.data.data &&
      indentItemsApi.data.data.length
    ) {
      setdata(indentItemsApi.data.data);
    }
  }, [indentItemsApi.data]);

  useEffect(() => {
    if (indentId) {
      retrieveIndentItems(indentId);
    }
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        return toast.error(x);
      });
    }
  }, [errors]);

  const retailIndentApi = useApi(retailersApi.retailerOrdersStaffAction);

  const handleCloseIndent = async () => {
    setopenYesNoModal(true);
  };

  const closeIndent = async () => {
    setErrors([]);
    setopenYesNoModal(false);
    const data = {
      action: "CloseRetailerIndent",
      indent: location.state.item.id,
    };
    console.log("data", data);
    await retailIndentApi.request(data);
  };

  const abortCloseIndent = () => {
    setopenYesNoModal(false);
  };

  useEffect(() => {
    console.log("retailIndentApi.data", retailIndentApi.data);
  }, [retailIndentApi.data]);

  useEffect(() => {
    if (retailIndentApi.data) {
      if (retailIndentApi.data.errors && retailIndentApi.data.errors.length) {
        setErrors(retailIndentApi.data.errors);
      }
    }

    console.log("retailIndentApi.data", retailIndentApi.data);
  }, [retailIndentApi.data]);

  return retailIndentApi.loading ? (
    <Loading loading={retailIndentApi.loading} />
  ) : (
    <div>
      {openYesNoModal && (
        <YesNoModal
          showModal={openYesNoModal}
          setShowModal={setopenYesNoModal}
          title="Close Indent"
          content="Indent shall be closed and orders created at respective wholesalers. This action is irreversible. Do you want to proceed?"
          yesAction={closeIndent}
          noAction={abortCloseIndent}
        />
      )}
      {screenSize.width < 768 ? (
        <div>
          <Card className="max-w-full rounded-sm">
            <ToastContainer position="bottom-center" theme="colored" />
            <CardBody className="overflow-hidden">
              <Tabs
                fullWidth
                size="md"
                aria-label="Tabs form"
                selectedKey={selected}
                onSelectionChange={setSelected}
              >
                <Tab key="products" title="Products">
                  <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
                    <h1 className="text-large font-bold text-center">
                      Products List
                    </h1>
                    {customerOrderActionsApi.loading ? (
                      <Loading loading={customerOrderActionsApi.loading} />
                    ) : (
                      <Card className="max-w-full mx-1 md:mx-5 my-1">
                        <CardBody>
                          <Input
                            label="Search"
                            isClearable
                            radius="lg"
                            onChange={(e) => handleFilter(e)}
                            classNames={{
                              label: "text-black/50 dark:text-white/90",
                              input: [
                                "bg-transparent",
                                "text-black/90 dark:text-white/90",
                                "placeholder:text-default-700/50 dark:placeholder:text-white/60",
                              ],
                              innerWrapper: "bg-transparent",
                              inputWrapper: [
                                "shadow-xl",
                                "bg-default-200/50",
                                "dark:bg-default/60",
                                "backdrop-blur-xl",
                                "backdrop-saturate-200",
                                "hover:bg-default-200/70",
                                "dark:hover:bg-default/70",
                                "group-data-[focused=true]:bg-default-200/50",
                                "dark:group-data-[focused=true]:bg-default/60",
                                "!cursor-text",
                              ],
                            }}
                            placeholder="Type to search..."
                            startContent={
                              <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                            }
                          />
                        </CardBody>
                      </Card>
                    )}
                    {data &&
                      data.length > 0 &&
                      data.map((item) => <p>{item.wholesaler.title}</p>)}
                  </div>
                </Tab>
                <Tab key="cart" title="Customer Order">
                  <div className="max-h-[720px] bg-gray-100 overflow-y-scroll my-2">
                    <h1 className="text-large font-bold text-center">
                      Indent Summary
                    </h1>
                    <Card className="max-w-full mx-1 md:mx-5 my-1">
                      <CardBody>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-y-2">
                          <div>
                            <p className="text-slate-500">Customer Name</p>
                            <p className="font-bold text-gray-400">
                              {selectedIndent && selectedIndent.customer_name}
                            </p>
                          </div>
                          <div>
                            <p className="text-slate-500">Customer Phone</p>
                            <p className="font-bold text-gray-400">
                              {selectedIndent && selectedIndent.customer_phone}
                            </p>
                          </div>

                          <div>
                            <p className="text-slate-500">Total Amount</p>
                            <p className="font-bold text-gray-400">
                              KES{" "}
                              {data &&
                                parseFloat(
                                  data.reduce(
                                    (acc, item) => acc + item.item_price_total,
                                    0
                                  )
                                ).toFixed(2)}
                            </p>
                          </div>

                          <div>
                            <p className="text-slate-500">Items in Order</p>
                            <p className="font-bold text-gray-400">
                              {data && data.length}
                            </p>
                          </div>
                        </div>
                      </CardBody>
                    </Card>

                    <Card className="max-w-full mx-1 md:mx-5 my-2 h-3">
                      <Button
                        size={30}
                        onClick={() => {}}
                        text="Save Order"
                        className="m-1"
                      >
                        Save Order
                      </Button>
                    </Card>
                  </div>
                </Tab>
              </Tabs>
            </CardBody>
          </Card>
        </div>
      ) : (
        <div className="grid md:grid-cols-2 gap-6">
          {loading ? (
            <Loading loading={loading} />
          ) : (
            <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
              <ToastContainer position="bottom-center" theme="colored" />
              <h1 className="text-large font-bold text-center">
                Products List
              </h1>

              <div className="max-w-full mx-1 md:mx-5  rounded-sm my-5">
                <CustomInput
                  size="large"
                  label="Filter"
                  isClearable
                  onChange={(e) => handleFilter(e)}
                  placeholder="Type to filter..."
                  startContent={
                    <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                  }
                />
              </div>

              {data &&
                data.length > 0 &&
                data.map((item) => (
                  <div>
                    <p className="text-center font-bold text-xl">
                      {item.wholesaler.title}
                    </p>
                    <div>
                      {item.items && item.items.length ? (
                        item.items.map((x) => {
                          return (
                            <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                              <CardHeader className="justify-between">
                                <div className="flex gap-5 items-center mx-2 justify-between w-full">
                                  <Avatar
                                    className="w-20 h-20 text-large"
                                    size="lg"
                                    src={
                                      x.images && x.images.length
                                        ? x.images[0].image
                                        : ""
                                    }
                                    name={x.wholesale_receipt_title}
                                  />
                                  <div className="flex flex-col items-start justify-center w-full">
                                    <h4 className="text-medium font-semibold leading-none text-default-600">
                                      {x.wholesale_receipt_title}
                                    </h4>
                                    <p className="text-medium tracking-tight text-default-400">
                                      {x.wholesaler_title}
                                    </p>

                                    <div className="flex flex-row justify-between w-full">
                                      <p className="text-medium tracking-tight text-default-400">
                                        KES {x.pack_selling_price}
                                      </p>
                                      <p className="text-medium tracking-tight text-default-400 ">
                                        Qty Required: {x.required_quantity}
                                      </p>
                                      <p className="text-medium tracking-tight text-default-400 text-start ">
                                        Discount:{" "}
                                        {x.price_discount_title
                                          ? x.price_discount_title
                                          : "None"}
                                      </p>
                                      <p className="text-medium tracking-tight text-default-400 text-start">
                                        Net: KES {x.final_pack_price}
                                      </p>
                                    </div>
                                    <div className="flex flex-row justify-between w-full">
                                      <div className="flex flex-row justify-between">
                                        {x.days_to_expiry &&
                                        x.days_to_expiry < 90 ? (
                                          <h6 className="text-medium tracking-tight text-red-600 pr-3">
                                            Expiry Date:{" "}
                                            {item.expiry_date
                                              ? item.expiry_date
                                              : "Not Indicated"}
                                          </h6>
                                        ) : (
                                          <h6 className="text-medium tracking-tight text-green-600">
                                            Expiry Date:{" "}
                                            {x.expiry_date
                                              ? x.expiry_date
                                              : "Not indicated"}
                                          </h6>
                                        )}
                                        {x.days_to_expiry &&
                                        x.days_to_expiry < 90 ? (
                                          <h6 className="text-medium tracking-tight text-red-600 pl-3">
                                            {x.expiry_status}
                                          </h6>
                                        ) : (
                                          <h6 className="text-medium tracking-tight text-green-600">
                                            {x.expiry_status}
                                          </h6>
                                        )}
                                      </div>
                                      <div>
                                        <BsTrash
                                          onClick={() =>
                                            handleRemoveFromIndent(x)
                                          }
                                          className="cursor-pointer hover:resize-x"
                                          size={36}
                                          color={dangerColor}
                                        />
                                      </div>
                                    </div>
                                  </div>
                                </div>
                              </CardHeader>
                            </Card>
                          );
                        })
                      ) : (
                        <div></div>
                      )}
                    </div>
                  </div>
                ))}
            </div>
          )}
          {data ? (
            <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
              <Card className="max-w-full mx-1 md:mx-5 my-1 rounded-sm">
                <CardHeader>
                  <CardTitle className="font-bold text-lg">
                    Indent Summary
                  </CardTitle>
                </CardHeader>
                <CardBody>
                  <div className="grid grid-cols-2 md:grid-cols-4">
                    <div>
                      <p className="text-slate-500">Items</p>
                      <p className="font-bold text-gray-400">
                        {location.state.item.retailer_indent_items.length}
                      </p>
                    </div>
                    <div>
                      <p className="text-slate-500">Order Days</p>
                      <p className="font-bold text-gray-400">
                        {location.state.item.order_days}
                      </p>
                    </div>
                    <div>
                      <p className="text-slate-500">Lead Time</p>
                      <p className="font-bold text-gray-400">
                        {location.state.item.lead_time}
                      </p>
                    </div>
                    <div>
                      <p className="text-slate-500">Is Open</p>
                      <p className="font-bold text-gray-400 uppercase">
                        {location.state.item.is_open}
                      </p>
                    </div>
                  </div>
                </CardBody>
              </Card>
              {selectedOrderItems &&
                selectedOrderItems.map((item) => (
                  <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                    <CardHeader className="justify-between">
                      <div className="grid md:grid-cols-12 w-full gap-x-2 grid-cols-1">
                        <Avatar
                          className="col-span-1 md:col-span-2 w-full h-full"
                          size="lg"
                          src={item.image ? item.image : ""}
                          name={item.title}
                        />
                        <div className="col-span-1  md:col-span-10 flex flex-col gap-y-2 items-start justify-center w-full">
                          <h4 className="text-medium font-semibold leading-none text-default-600">
                            {item.product_title}
                          </h4>

                          <div className="w-full">
                            <p className="font-semibold text-lg border-b-2">
                              Quantities
                            </p>
                            <div className="flex  justify-between w-full">
                              {item.purchased_quantity >
                                item.available_quantity && (
                                <p className="text-red-500">
                                  <span>Required Quantity: </span>
                                  {item.purchased_quantity ? (
                                    <span>{item.purchased_quantity}</span>
                                  ) : (
                                    <span>0</span>
                                  )}
                                </p>
                              )}
                              {item.purchased_quantity <=
                                item.available_quantity && (
                                <p className="text-green-500">
                                  <span>Required Quantity: </span>
                                  {item.purchased_quantity ? (
                                    <span>{item.purchased_quantity}</span>
                                  ) : (
                                    <span>0</span>
                                  )}
                                </p>
                              )}

                              <p>
                                <span>Available Quantity: </span>
                                {item.available_quantity ? (
                                  <span>{item.available_quantity}</span>
                                ) : (
                                  <span>0</span>
                                )}
                              </p>
                              <Edit
                                onClick={() => {}}
                                className="cursor-pointer"
                                color="primary"
                              />
                              <RefreshRounded
                                className="cursor-pointer"
                                color="primary"
                              />
                            </div>
                          </div>
                          <div className="w-full">
                            <p className="font-semibold text-lg border-b-2">
                              Pricing
                            </p>
                            <div className="flex  justify-between w-full">
                              <p>
                                <span>Unit Selling Price: </span>
                                {item.unit_selling_price ? (
                                  <span>KES {item.unit_selling_price}</span>
                                ) : (
                                  <span>KES 0.00</span>
                                )}
                              </p>
                            </div>
                          </div>
                          <div className="w-full">
                            <p className="font-semibold text-lg border-b-2">
                              Discount
                            </p>
                            <div className="flex  justify-between w-full">
                              <p>
                                <span>Counter Discount: </span>
                                {item.item_counter_price_discount ? (
                                  <span>
                                    {item.item_counter_price_discount} %{" "}
                                  </span>
                                ) : (
                                  <span>0 %</span>
                                )}
                              </p>
                              <p>
                                <span>Discount Selling Price: </span>
                                {item.discounted_counter_selling_price ? (
                                  <span>
                                    KES{" "}
                                    {parseFloat(
                                      item.discounted_counter_selling_price
                                    ).toString()}{" "}
                                  </span>
                                ) : (
                                  <span>KES 0.00</span>
                                )}
                              </p>
                              <p>
                                <span>Discount Item Amount: </span>
                                {item.item_counter_price_discount_amount ? (
                                  <span>
                                    KES{" "}
                                    {parseFloat(
                                      item.item_counter_price_discount_amount
                                    ).toString()}{" "}
                                  </span>
                                ) : (
                                  <span>KES 0.00</span>
                                )}
                              </p>
                            </div>
                          </div>

                          <div className="w-full">
                            <p className="font-semibold text-lg border-b-2">
                              Item Total Amount
                            </p>
                            <div className="flex  justify-between w-full">
                              <p>
                                <span>Item Total: </span>
                                {item.item_price_total ? (
                                  <span>KES {item.item_price_total}</span>
                                ) : (
                                  <span>0 %</span>
                                )}
                              </p>
                              <p>
                                <span>Net Item Total: </span>
                                {item.item_net_price_total ? (
                                  <span>
                                    KES{" "}
                                    {parseFloat(
                                      item.item_net_price_total
                                    ).toFixed(2)}{" "}
                                  </span>
                                ) : (
                                  <span>KES 0.00</span>
                                )}
                              </p>
                            </div>
                          </div>
                        </div>
                      </div>
                    </CardHeader>

                    <CardFooter className="flex flex-row justify-between">
                      {/* <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} /> */}
                      {/* <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} /> */}
                      <DiscountTwoTone onClick={() => {}} color="success" />
                      <DeleteForeverTwoTone
                        onClick={() => {}}
                        fontSize="large"
                        className="text-red-700 text-lg hover:text-red-400"
                      />
                    </CardFooter>
                  </Card>
                ))}

              <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                <CardBody>
                  <div>
                    <p>INDENT VALUE</p>
                    <p>
                      {" "}
                      KES{" "}
                      {parseFloat(
                        getTotalValue(location.state.item.retailer_indent_items)
                      ).toFixed(2)}
                    </p>
                  </div>
                </CardBody>
              </Card>
              {location.state.item.is_open === "true" ? (
                <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                  <Button
                    style={{ background: currentColor, color: "white" }}
                    size="lg"
                    radius="none"
                    text="Close Indent"
                    onClick={() => handleCloseIndent()}
                    className="m-1"
                  >
                    Close Indent
                  </Button>
                </Card>
              ) : (
                <div></div>
              )}
            </div>
          ) : (
            <div></div>
          )}
        </div>
      )}
    </div>
  );
}

export default RetailerIndentDetails;
